mapper.select:
SELECT * FROM TBL_SYSTEM_ACTIVITY
WHERE COMPANY_ID = #{companyId}
ORDER BY CREATE_TIME DESC
LIMIT #{limit}

SELECT * FROM TBL_SYSTEM_ACTIVITY
WHERE USER_ID = #{userId}
AND COMPANY_ID = #{companyId}
ORDER BY CREATE_TIME DESC
LIMIT #{limit}

SELECT * FROM TBL_SYSTEM_ACTIVITY
WHERE MODULE_NAME = #{moduleName}
AND COMPANY_ID = #{companyId}
ORDER BY CREATE_TIME DESC
LIMIT #{limit}

SELECT * FROM TBL_SYSTEM_ACTIVITY
WHERE TARGET_TYPE = #{targetType}
AND TARGET_ID = #{targetId}
AND COMPANY_ID = #{companyId}
ORDER BY CREATE_TIME DESC

SELECT COUNT(*) FROM TBL_SYSTEM_ACTIVITY
WHERE ACTION = #{action}
AND CREATE_TIME BETWEEN #{startTime} AND #{endTime}
AND COMPANY_ID = #{companyId}

SELECT AVG(EXECUTE_TIME) FROM TBL_SYSTEM_ACTIVITY
WHERE ACTION = #{action}
AND CREATE_TIME BETWEEN #{startTime} AND #{endTime}
AND COMPANY_ID = #{companyId}
AND EXECUTE_TIME IS NOT NULL

mapper.delete:
DELETE FROM TBL_SYSTEM_ACTIVITY
WHERE CREATE_TIME < #{beforeDate}
AND COMPANY_ID = #{companyId}
